\begin{pmatrix}
\mu(b)/b&[\mu(b)+\mu(c)]/(b+c)\\
[\mu(b)+\mu(c)]/(b+c)&\mu(c)/c
\end{pmatrix}
\succeq0.
}
\tag{V23}
$$

